startingSql:
SELECT product_id, SUM(quantity) / COUNT(*) AS avg_qty
FROM order_items
GROUP BY product_id;

solutionSql:
SELECT product_id, ROUND(1.0 * SUM(quantity) / COUNT(*), 2) AS avg_qty
FROM order_items
GROUP BY product_id;

startingSql:
SELECT order_id, customer_name, amount FROM source_orders
UNION
SELECT order_id, customer_name, amount FROM warehouse_orders;

solutionSql:
SELECT order_id, customer_name, amount FROM source_orders
UNION ALL
SELECT order_id, customer_name, amount FROM warehouse_orders;

startingSql:
SELECT e.name
FROM employees e
WHERE EXISTS (
  SELECT 1 FROM employees e2 WHERE e2.salary = e.salary
);

solutionSql:
SELECT e.name
FROM employees e
WHERE EXISTS (
  SELECT 1 FROM employees e2 WHERE e2.salary = e.salary AND e2.id <> e.id
);

startingSql:
SELECT name,
  ROUND(AVG(salary) OVER (ORDER BY hire_date, id ROWS BETWEEN CURRENT ROW AND 2 FOLLOWING), 2) AS trailing_avg
FROM employees;

solutionSql:
SELECT name,
  ROUND(AVG(salary) OVER (ORDER BY hire_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS trailing_avg
FROM employees;

startingSql:
SELECT order_id FROM source_orders EXCEPT SELECT order_id FROM warehouse_orders
UNION
SELECT order_id FROM warehouse_orders EXCEPT SELECT order_id FROM source_orders;

solutionSql:
SELECT order_id FROM (SELECT order_id FROM source_orders EXCEPT SELECT order_id FROM warehouse_orders)
UNION
SELECT order_id FROM (SELECT order_id FROM warehouse_orders EXCEPT SELECT order_id FROM source_orders);
